head.script:
scwin.onpageload = function() {
	scwin.startCnt = 0;
    var data = [];
    for (var i = scwin.startCnt; i < scwin.startCnt + 20; i++) {
        data.push(i + "");
        data.push(i + "" + "_v");
    }
    scwin.startCnt += 20;
    dataList1.setData(data);
    var data_grd = [];
    for (var i = 0; i < 100; i++) {
        data_grd.push(i + "_0");
        data_grd.push("");
        data_grd.push("");
        data_grd.push(i + "_3");
    }
    dataList_grd.setData(data_grd);
};
scwin.onpageunload = function() {};
scwin.trigger1_onclick = function(e) {
    var data = [];
    for (var i = scwin.startCnt; i < scwin.startCnt + 20; i++) {
        data.push(i + "");
        data.push(i + "" + "_v");
    }
    dataList1.setData(data, true);
    scwin.startCnt += 20;
};
scwin.trigger2_onclick = function(e) {
    var data = [];
    for (var i = scwin.startCnt; i < scwin.startCnt + 100; i++) {
        data.push(i + "");
        data.push(i + "" + "_v");
    }
    dataList1.setData(data, true);
    scwin.startCnt += 100;
};
scwin.trigger3_onclick = function(e) {
    var data = [];
    for (var i = scwin.startCnt; i < scwin.startCnt + 1000; i++) {
        data.push(i + "");
        data.push(i + "" + "_v");
    }
    dataList1.setData(data, true);
    scwin.startCnt += 1000;
};
scwin.simulateWrapper = function(target, type, options) {
    WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.setSimulate1 = function() {
    scwin.simulateWrapper('#G_gridView1___checkcombobox_col2_input', 'key-sequence', {
        sequence: '1,5-8,'
    });
}
scwin.setSimulate2 = function() {
    scwin.simulateWrapper('#G_gridView1___checkcombobox_col2_input', 'key-combo', {
        combo: 'ENTER'
    });
}
scwin.Dbclick = function(id) {
    var el = WebSquare.wUnit.getDomById($p.id + id);
    scwin.fireDbClick(el);
}
scwin.fireDbClick = function(node) {
    if (document.createEventObject) {
        node.fireEvent('ondblclick');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('dblclick', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.ondblclick == 'function') {
        node.ondblclick();
    }
}
scwin.checkVal = function() {
    if (WebSquare.wUnit.getDomById($p.id + 'G_gridView1___checkcombobox_col2_itemTable_1_checkbox').checked == true &&
        WebSquare.wUnit.getDomById($p.id + 'G_gridView1___checkcombobox_col2_itemTable_5_checkbox').checked == true &&
        WebSquare.wUnit.getDomById($p.id + 'G_gridView1___checkcombobox_col2_itemTable_6_checkbox').checked == true &&
        WebSquare.wUnit.getDomById($p.id + 'G_gridView1___checkcombobox_col2_itemTable_7_checkbox').checked == true &&
        WebSquare.wUnit.getDomById($p.id + 'G_gridView1___checkcombobox_col2_itemTable_8_checkbox').checked == true) {
        return true;
    } else {
        return false;
    }
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.Dbclick($p.id+'gridView1_cell_0_1')");
    WebSquare.wUnit.addCommand('pause', '500');
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('G_gridView1___checkcombobox_col2_label').click()");
    WebSquare.wUnit.addCommand('pause', '500');
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand('pause', '500');
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate2()");
    WebSquare.wUnit.addCommand('pause', '500');
    WebSquare.wUnit.addCommand("set", "scwin.Dbclick($p.id+'gridView1_cell_0_1')");
    WebSquare.wUnit.addCommand('pause', '500');
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
